                        ) : (
                            <button className="login-btn" onClick={() => navigate("/login")}>
                                Login
                            </button>
                        )}
                    </nav>
                </header>

                <h1 className="page-title">YouTube Video Clipper</h1>

                <div className="url-input-container">
                    <input
                        type="text"
                        placeholder="Enter YouTube URL"
                        value={videoURL}
                        onChange={(e) => setVideoURL(e.target.value)}
                        className="url-input"
                        disabled={processing}
                    />
